IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.local(uuid,uuid,boolean)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='9eb2f0d8b7e52d5280f0798c48cb8ec84377281c1e13706bc066b1cf3765070b' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.local(uuid,uuid,boolean)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_contexto_v2(date,uuid)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='e5ca6e224708a655a9c778fa6a5701b39e6c0aab8dbf0a01a87ffb77d42ea095' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner AND x.grantee<>'authenticated'::regrole)) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: public.fn_folha_contexto_v2(date,uuid)';END IF;
END $hours_dependencies$;DO $functions$ BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_destino_operar_v3(jsonb,boolean,text)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='54f892399e319a1975b4ed1d6173f0da5e773adf5ca10bce46245c7c8a8f18b4' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) a WHERE a.grantee<>proowner AND a.grantee<>'authenticated'::regrole)) THEN RAISE EXCEPTION 'ADDON_FUNCTION_DRIFT: public.fn_folha_destino_operar_v3(jsonb,boolean,text)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_relatorio_horas_v3(uuid,date,date,text,uuid)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='b185fb111d185f19fceb2f0f2ffac1d473ae5b324a9a589b815304cd096f3b9d' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) a WHERE a.grantee<>proowner AND a.grantee<>'authenticated'::regrole)) THEN RAISE EXCEPTION 'ADDON_FUNCTION_DRIFT: public.fn_folha_relatorio_horas_v3(uuid,date,date,text,uuid)';END IF;END $functions$;DO $functions$ BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;
END $functions$;DO $absent$ BEGIN IF to_regprocedure('folha_privado.externo_mes_v3(uuid,uuid,date)') IS NOT NULL OR to_regprocedure('folha_privado.externo_confirmacao_guardar_v3()') IS NOT NULL OR to_regprocedure('public.fn_folha_externos_confirmar_v3(jsonb,boolean,text)') IS NOT NULL OR to_regprocedure('public.fn_folha_externos_excel_contexto_v3(uuid,uuid,date)') IS NOT NULL OR to_regprocedure('public.fn_folha_externos_conferencia_contexto_v3(uuid,uuid,date)') IS NOT NULL OR to_regclass('public.folha_externos_confirmacoes') IS NOT NULL THEN RAISE EXCEPTION 'ADDON_PRESENT_OR_PARTIAL';END IF;END $absent$;DO $data$ DECLARE r record;j jsonb;BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;IF NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname='primeline_externo_mes_backup' AND nspowner='postgres'::regrole) OR EXISTS(SELECT 1 FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a WHERE n.nspname='primeline_externo_mes_backup' AND a.grantee<>n.nspowner) OR EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE n.nspname='primeline_externo_mes_backup' AND a.grantee<>c.relowner) OR EXISTS(SELECT 1 FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='primeline_externo_mes_backup' AND a.attnum>0 AND NOT a.attisdropped AND a.attacl IS NOT NULL AND a.attacl<>'{}'::aclitem[]) THEN RAISE EXCEPTION 'ADDON_BACKUP_NOT_PRIVATE';END IF;FOR r IN SELECT * FROM primeline_externo_mes_backup.dados LOOP EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text COLLATE "C"),''[]''::jsonb) FROM %s x',r.tabela::regclass) INTO j;IF j IS DISTINCT FROM r.linhas THEN RAISE EXCEPTION 'ADDON_DATA_DRIFT';END IF;END LOOP;END $data$;CREATE TABLE public.folha_externos_confirmacoes(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),empresa_id uuid NOT NULL REFERENCES public.empresas(id),obra_id uuid NOT NULL REFERENCES public.obras(id),fornecedor_id uuid NOT NULL REFERENCES public.fornecedores(id),competencia date NOT NULL CHECK(isfinite(competencia) AND extract(day FROM competencia)=1),revision integer NOT NULL CHECK(revision>0),facts_fingerprint text NOT NULL CHECK(facts_fingerprint ~ '^[0-9a-f]{64}$'),snapshot jsonb NOT NULL CHECK(jsonb_typeof(snapshot)='object'),confirmado_por uuid NOT NULL REFERENCES public.utilizadores(id),confirmado_em timestamptz NOT NULL DEFAULT now(),request_id uuid NOT NULL,reason text,UNIQUE(empresa_id,obra_id,fornecedor_id,competencia,revision),UNIQUE(empresa_id,confirmado_por,request_id)
);ALTER TABLE public.folha_externos_confirmacoes ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.folha_externos_confirmacoes FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION folha_privado.externo_mes_v3(w uuid,provider uuid,m date) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $month$
DECLARE u public.utilizadores;r jsonb;hash text;
BEGIN
 u:=folha_privado.ator();IF w IS NULL OR provider IS NULL OR m IS NULL OR NOT isfinite(m) OR extract(day FROM m)<>1 THEN RAISE EXCEPTION 'MONTH_REQUIRED';END IF;
 r:=public.fn_folha_relatorio_horas_v3(w,m,(m+interval '1 month')::date-1,'external',provider);
 hash:=encode(sha256(convert_to(jsonb_build_array('external_month_v3',u.empresa_id,w,provider,m,r->'records')::text,'UTF8')),'hex');RETURN r||jsonb_build_object('facts_fingerprint',hash,'month',m,'provider_id',provider);
END $month$;
CREATE FUNCTION folha_privado.externo_confirmacao_guardar_v3() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog AS $guard$
DECLARE u public.utilizadores;c public.folha_externos_confirmacoes;r jsonb;
BEGIN
 IF current_user<>'postgres' OR TG_OP<>'INSERT' THEN RAISE EXCEPTION 'EXTERNAL_CONFIRMATION_PROTECTED' USING ERRCODE='42501';END IF;u:=folha_privado.ator();
 IF u.funcao<>'diretor_obra' OR NEW.empresa_id<>u.empresa_id OR NEW.confirmado_por<>u.id OR NEW.confirmado_em IS DISTINCT FROM now() THEN RAISE EXCEPTION 'PERMISSION_DENIED' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM public.obra_responsaveis WHERE obra_id=NEW.obra_id AND utilizador_id=u.id AND papel='diretor_obra';IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED' USING ERRCODE='42501';END IF;
 SELECT * INTO c FROM public.folha_externos_confirmacoes WHERE empresa_id=u.empresa_id AND obra_id=NEW.obra_id AND fornecedor_id=NEW.fornecedor_id AND competencia=NEW.competencia ORDER BY revision DESC LIMIT 1;
 IF NEW.revision<>coalesce(c.revision,0)+1 THEN RAISE EXCEPTION 'STALE_REVISION' USING ERRCODE='40001';END IF;
 r:=folha_privado.externo_mes_v3(NEW.obra_id,NEW.fornecedor_id,NEW.competencia);IF NEW.snapshot IS DISTINCT FROM r OR NEW.facts_fingerprint IS DISTINCT FROM r->>'facts_fingerprint' THEN RAISE EXCEPTION 'STALE_SOURCE' USING ERRCODE='40001';END IF;RETURN NEW;
END $guard$;
CREATE TRIGGER folha_externos_confirmacao_guardar BEFORE INSERT OR UPDATE OR DELETE ON public.folha_externos_confirmacoes FOR EACH ROW EXECUTE FUNCTION folha_privado.externo_confirmacao_guardar_v3();
CREATE FUNCTION public.fn_folha_externos_confirmar_v3(p_dados jsonb,p_confirmar boolean DEFAULT false,p_versao text DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $confirm$
DECLARE u public.utilizadores;req uuid:=(p_dados->>'request_id')::uuid;w uuid:=(p_dados->>'work_id')::uuid;provider uuid:=(p_dados->>'provider_id')::uuid;m date:=(p_dados->>'month')::date;old public.folha_externos_confirmacoes;n public.folha_externos_confirmacoes;r jsonb;payload jsonb;token text;result jsonb;op folha_privado.operacoes;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'RETRY_READ_COMMITTED' USING ERRCODE='40001';END IF;
 LOCK TABLE public.quadro_pessoal_alocacao IN ROW EXCLUSIVE MODE;PERFORM pg_advisory_xact_lock(61001,1);u:=folha_privado.ator();PERFORM 1 FROM public.utilizadores WHERE id=u.id FOR SHARE;u:=folha_privado.ator();IF (p_dados ? 'empresa_id' AND (p_dados->>'empresa_id')::uuid IS DISTINCT FROM u.empresa_id) OR (p_dados ? 'company_id' AND (p_dados->>'company_id')::uuid IS DISTINCT FROM u.empresa_id) THEN RAISE EXCEPTION 'TENANT_HINT_MISMATCH' USING ERRCODE='42501';END IF;PERFORM 1 FROM public.utilizadores WHERE id=u.id FOR SHARE;u:=folha_privado.ator();
 IF u.funcao<>'diretor_obra' THEN RAISE EXCEPTION 'PERMISSION_DENIED: confirmação do Diretor' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM public.obras WHERE id=w AND empresa_id=u.empresa_id FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM public.obra_responsaveis WHERE obra_id=w AND utilizador_id=u.id AND papel='diretor_obra' FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED' USING ERRCODE='42501';END IF;
 IF req IS NULL OR p_confirmar IS NULL OR (p_dados->>'version')::integer IS DISTINCT FROM 3 OR provider IS NULL OR m IS NULL THEN RAISE EXCEPTION 'VALIDATION_ERROR';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_dados) x WHERE x NOT IN('version','request_id','work_id','provider_id','month','expected_revision','reason')) THEN RAISE EXCEPTION 'UNKNOWN_FIELD';END IF;
 payload:=jsonb_build_object('action','external_confirm','data',p_dados);SELECT * INTO op FROM folha_privado.operacoes WHERE empresa_id=u.empresa_id AND ator_id=u.id AND request_id=req;
 IF FOUND THEN IF op.payload IS DISTINCT FROM payload THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT';END IF;IF NOT p_confirmar THEN RETURN jsonb_build_object('version',3,'committed',false,'versao',op.token);END IF;IF p_versao IS DISTINCT FROM op.token THEN RAISE EXCEPTION 'STALE_PREVIEW' USING ERRCODE='40001';END IF;RETURN op.resultado;END IF;
 PERFORM 1 FROM public.folha_registos f JOIN public.folha_externos e ON e.id=f.externo_id WHERE f.empresa_id=u.empresa_id AND f.obra_id=w AND e.fornecedor_id=provider AND f.data>=m AND f.data<(m+interval '1 month')::date FOR SHARE OF f;
 SELECT * INTO old FROM public.folha_externos_confirmacoes WHERE empresa_id=u.empresa_id AND obra_id=w AND fornecedor_id=provider AND competencia=m ORDER BY revision DESC LIMIT 1 FOR UPDATE;
 IF (p_dados->>'expected_revision')::integer IS DISTINCT FROM coalesce(old.revision,0) THEN RAISE EXCEPTION 'STALE_REVISION' USING ERRCODE='40001';END IF;
 IF old.id IS NOT NULL AND nullif(btrim(p_dados->>'reason'),'') IS NULL THEN RAISE EXCEPTION 'CORRECTION_REASON_REQUIRED';END IF;
 r:=folha_privado.externo_mes_v3(w,provider,m);IF EXISTS(SELECT 1 FROM jsonb_array_elements(r->'records') x WHERE (x->>'open')::boolean) THEN RAISE EXCEPTION 'EXTERNAL_OPEN_INTERVALS';END IF;
 token:=encode(sha256(convert_to(jsonb_build_object('actor',u.id,'tenant',u.empresa_id,'payload',payload,'before',to_jsonb(old),'source',r)::text,'UTF8')),'hex');IF NOT p_confirmar THEN RETURN jsonb_build_object('version',3,'committed',false,'versao',token,'preview',r);END IF;IF p_versao IS DISTINCT FROM token THEN RAISE EXCEPTION 'STALE_PREVIEW' USING ERRCODE='40001';END IF;
 INSERT INTO public.folha_externos_confirmacoes(empresa_id,obra_id,fornecedor_id,competencia,revision,facts_fingerprint,snapshot,confirmado_por,request_id,reason) VALUES(u.empresa_id,w,provider,m,coalesce(old.revision,0)+1,r->>'facts_fingerprint',r,u.id,req,p_dados->>'reason') RETURNING * INTO n;
 result:=jsonb_build_object('version',3,'committed',true,'request_id',req,'confirmation_id',n.id,'revision',n.revision,'facts_fingerprint',n.facts_fingerprint);INSERT INTO folha_privado.operacoes VALUES(u.empresa_id,u.id,req,payload,token,result,now());RETURN result;
END $confirm$;
CREATE FUNCTION public.fn_folha_externos_excel_contexto_v3(p_obra_id uuid,p_fornecedor_id uuid,p_competencia date) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $export$
DECLARE u public.utilizadores;c public.folha_externos_confirmacoes;r jsonb;
BEGIN
 u:=folha_privado.ator();r:=folha_privado.externo_mes_v3(p_obra_id,p_fornecedor_id,p_competencia);
 SELECT * INTO c FROM public.folha_externos_confirmacoes WHERE empresa_id=u.empresa_id AND obra_id=p_obra_id AND fornecedor_id=p_fornecedor_id AND competencia=p_competencia ORDER BY revision DESC LIMIT 1;
 IF c.id IS NULL OR c.facts_fingerprint IS DISTINCT FROM r->>'facts_fingerprint' THEN RAISE EXCEPTION 'EXTERNAL_CONFIRMATION_REQUIRED: confirmar a revisão atual';END IF;
 RETURN jsonb_build_object('version',3,'server_authorized',true,'export_format','xlsx','confirmed_by_role','diretor_obra','confirmation_id',c.id,'revision',c.revision,'facts_fingerprint',c.facts_fingerprint,'confirmed_by',c.confirmado_por,'confirmed_at',c.confirmado_em,'report',r,'financial_effect',false);
END $export$;
REVOKE ALL ON FUNCTION folha_privado.externo_mes_v3(uuid,uuid,date),folha_privado.externo_confirmacao_guardar_v3(),public.fn_folha_externos_confirmar_v3(jsonb,boolean,text),public.fn_folha_externos_excel_contexto_v3(uuid,uuid,date) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.fn_folha_externos_confirmar_v3(jsonb,boolean,text),public.fn_folha_externos_excel_contexto_v3(uuid,uuid,date) TO authenticated;
CREATE FUNCTION public.fn_folha_externos_conferencia_contexto_v3(p_obra_id uuid,p_fornecedor_id uuid,p_competencia date) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $context$
DECLARE u public.utilizadores;r jsonb;c public.folha_externos_confirmacoes;h jsonb;
BEGIN
 u:=folha_privado.ator();r:=folha_privado.externo_mes_v3(p_obra_id,p_fornecedor_id,p_competencia);
 SELECT * INTO c FROM public.folha_externos_confirmacoes WHERE empresa_id=u.empresa_id AND obra_id=p_obra_id AND fornecedor_id=p_fornecedor_id AND competencia=p_competencia ORDER BY revision DESC LIMIT 1;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',x.id,'revision',x.revision,'confirmed_by',x.confirmado_por,'author_name',a.nome,'confirmed_at',x.confirmado_em,'reason',x.reason,'facts_fingerprint',x.facts_fingerprint) ORDER BY x.revision),'[]') INTO h FROM public.folha_externos_confirmacoes x LEFT JOIN public.utilizadores a ON a.id=x.confirmado_por AND a.empresa_id=u.empresa_id WHERE x.empresa_id=u.empresa_id AND x.obra_id=p_obra_id AND x.fornecedor_id=p_fornecedor_id AND x.competencia=p_competencia;
 RETURN jsonb_build_object('version',3,'work_id',p_obra_id,'provider_id',p_fornecedor_id,'month',p_competencia,'report',r,'expected_revision',coalesce(c.revision,0),'confirmation_current',c.id IS NOT NULL AND c.facts_fingerprint IS NOT DISTINCT FROM r->>'facts_fingerprint','can_confirm',u.funcao='diretor_obra' AND EXISTS(SELECT 1 FROM public.obra_responsaveis WHERE obra_id=p_obra_id AND utilizador_id=u.id AND papel='diretor_obra'),'history',h,'financial_effect',false);
END $context$;
REVOKE ALL ON FUNCTION public.fn_folha_externos_conferencia_contexto_v3(uuid,uuid,date) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.fn_folha_externos_conferencia_contexto_v3(uuid,uuid,date) TO authenticated;
INSERT INTO primeline_externo_mes_backup.estrutura VALUES('public.folha_externos_confirmacoes',jsonb_build_object('columns',(SELECT jsonb_agg(jsonb_build_array(a.attname,a.atttypid,a.atttypmod,a.attnotnull,a.attidentity,pg_get_expr(d.adbin,d.adrelid),a.attacl) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid='public.folha_externos_confirmacoes'::regclass AND a.attnum>0 AND NOT a.attisdropped),'constraints',(SELECT jsonb_agg(pg_get_constraintdef(oid) ORDER BY conname) FROM pg_constraint WHERE conrelid='public.folha_externos_confirmacoes'::regclass),'triggers',(SELECT jsonb_agg(jsonb_build_array(pg_get_triggerdef(oid),tgenabled,tgdeferrable,tginitdeferred) ORDER BY tgname) FROM pg_trigger WHERE tgrelid='public.folha_externos_confirmacoes'::regclass AND NOT tgisinternal),'indices',(SELECT jsonb_agg(pg_get_indexdef(indexrelid) ORDER BY indexrelid::regclass::text) FROM pg_index WHERE indrelid='public.folha_externos_confirmacoes'::regclass),'rls',(SELECT jsonb_build_array(relrowsecurity,relforcerowsecurity,relowner,relacl) FROM pg_class WHERE oid='public.folha_externos_confirmacoes'::regclass),'policies',(SELECT jsonb_agg(to_jsonb(x) ORDER BY x.polname) FROM pg_policy x WHERE x.polrelid='public.folha_externos_confirmacoes'::regclass))) ON CONFLICT(tabela) DO UPDATE SET estrutura=excluded.estrutura;DO $hours_dependencies$ BEGIN
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.ator()') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='176c4fb030401fb45c89f3cd1616a9d26e9e15b691ff524a33dfc8d233c6b079' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.ator()';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.obra(uuid,boolean)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='731f5289cd29bdb7f7d69723fabb76cbb8b8e577bb474c679f991c7271d9788e' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.obra(uuid,boolean)';END IF;
