e,tginitdeferred) ORDER BY tgname) FROM pg_trigger WHERE tgrelid='public.folha_externos_confirmacoes'::regclass AND NOT tgisinternal),'indices',(SELECT jsonb_agg(pg_get_indexdef(indexrelid) ORDER BY indexrelid::regclass::text) FROM pg_index WHERE indrelid='public.folha_externos_confirmacoes'::regclass),'rls',(SELECT jsonb_build_array(relrowsecurity,relforcerowsecurity,relowner,relacl) FROM pg_class WHERE oid='public.folha_externos_confirmacoes'::regclass),'policies',(SELECT jsonb_agg(to_jsonb(x) ORDER BY x.polname) FROM pg_policy x WHERE x.polrelid='public.folha_externos_confirmacoes'::regclass)) INTO j;IF j IS DISTINCT FROM (SELECT estrutura FROM primeline_externo_mes_backup.estrutura WHERE tabela='public.folha_externos_confirmacoes') THEN RAISE EXCEPTION 'ADDON_STRUCTURE_DRIFT';END IF;IF EXISTS(SELECT 1 FROM public.folha_externos_confirmacoes) THEN RAISE EXCEPTION 'ADDON_USED_ROLLBACK_OR_POSTCHECK';END IF;END $table$;DO $data$ DECLARE r record;j jsonb;BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;IF NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname='primeline_externo_mes_backup' AND nspowner='postgres'::regrole) OR EXISTS(SELECT 1 FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a WHERE n.nspname='primeline_externo_mes_backup' AND a.grantee<>n.nspowner) OR EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE n.nspname='primeline_externo_mes_backup' AND a.grantee<>c.relowner) OR EXISTS(SELECT 1 FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='primeline_externo_mes_backup' AND a.attnum>0 AND NOT a.attisdropped AND a.attacl IS NOT NULL AND a.attacl<>'{}'::aclitem[]) THEN RAISE EXCEPTION 'ADDON_BACKUP_NOT_PRIVATE';END IF;FOR r IN SELECT * FROM primeline_externo_mes_backup.dados LOOP EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text COLLATE "C"),''[]''::jsonb) FROM %s x',r.tabela::regclass) INTO j;IF j IS DISTINCT FROM r.linhas THEN RAISE EXCEPTION 'ADDON_DATA_DRIFT';END IF;END LOOP;END $data$;COMMIT;
